test("足し合わせで端数が出る角度の合計は、端数を落とした値になる", () => {
  expect(Angle.sum([0.1, 0.2])).toBe(0.3);
});

test("6 桁より細かい角度は、1 つずつ丸めずに合計してから丸める", () => {
  expect(Angle.sum([0.0000004, 0.0000004])).toBe(0.000001);
});

test("何も足さない合計は 0 になる", () => {
  expect(Angle.sum([])).toBe(0);
});

test("3 段の入れ子で角度の合計が 1 回りの倍数になるノードは、回っていない向きになる", () => {
  const document = DesignDocument.create({
    artboards: [
      {
        name: "home",
        width: 360,
        height: 240,
        children: [
          {
            name: "outer",
            type: "Box",
            props: { rotation: -0.1 },
            children: [
              {
                name: "parent",
                type: "Box",
                props: { rotation: -0.2 },
                children: [
                  { name: "self", type: "Text", props: { rotation: 0.3 } },
                ],
              },
            ],
          },
        ],
      },
    ],
  });

  // 合計は丸めで -0 になりうるので、0 との toEqual ではなく 360 度の倍数かで見る
  expect(
    Option.map(
      DesignDocument.totalRotationOf(document, "self"),
      Angle.isWholeTurns,
    ),
  ).toEqual(Option.some(true));
});

test("-128.3 度の子と 15.8 度の Box の合計は、端数の無い -112.5 度になる", () => {
  const document = DesignDocument.create({
    artboards: [
      {
        name: "home",
        width: 360,
        height: 240,
        children: [
          {
            name: "card",
            type: "Box",
            props: { rotation: 15.8 },
            children: [
              { name: "badge", type: "Text", props: { rotation: -128.3 } },
            ],
          },
        ],
      },
    ],
  });

  expect(DesignDocument.totalRotationOf(document, "badge")).toEqual(
    Option.some(-112.5),
  );
});

test("6 桁より細かい角度が入れ子で重なったノードの向きは、合計してから 6 桁へ丸める", () => {
  const document = DesignDocument.create({
    artboards: [
      {
        name: "home",
        width: 360,
        height: 240,
        children: [
          {
            name: "outer",
            type: "Box",
            props: { rotation: 0.0000004 },
            children: [
              {
                name: "parent",
                type: "Box",
                props: { rotation: 0.0000004 },
                children: [
                  {
                    name: "self",
                    type: "Text",
                    props: { rotation: 0.0000004 },
                  },
                ],
              },
            ],
          },
        ],
      },
    ],
  });

  expect(DesignDocument.totalRotationOf(document, "self")).toEqual(
    Option.some(0.000001),
  );
});

test("小数点以下 6 桁より細かく書いた子の角度は、6 桁へ丸めた角度で並ぶ", () => {
  const document = DesignDocument.create({
    artboards: [
      {
        name: "home",
        width: 360,
        height: 240,
        children: [
          { name: "card", type: "Box", props: { rotation: 12.3456789 } },
        ],
      },
    ],
  });

  expect(DesignDocument.collectArtboardChildRotations(document)).toEqual([
    { name: "card", rotation: 12.345679 },
  ]);
});

test("359.8 度の絶対配置の Box の中にある -719.8 度の絶対配置のノードは、揃え先を持つ", () => {
  // 角度を素のまま足すと -359.99999999999994 になり、1 回りの倍数から外れる
  const placed = (rotation: number) => ({
    widthMode: "fixed",
    width: 40,
    heightMode: "fixed",
    height: 20,
    placement: "absolute",
    x: 10,
    y: 10,
    rotation,
  });
  const selection = DocumentSelection.fromNames(
    DesignDocument.create({
      artboards: [
        {
          name: "home",
          width: 360,
          height: 240,
          children: [
            {
              name: "card",
              type: "Box",
              props: { ...placed(359.8), width: 120, height: 80 },
              children: [
                {
                  name: "badge",
                  type: "Box",
                  props: placed(-719.8),
                  children: [],
                },
              ],
            },
          ],
        },
      ],
    }),
    ["badge"],
  );

  expect(NodeResize.resizable(selection).snapTargetNames).toEqual(["card"]);
});

/* 以下は丸めた向きどうしの差・和に出る浮動小数の端数（丸める理由は `Angle.roundToMicrodegree`）。 */
test("512.2 度回って描かれる親から 152.2 度の親へ付け替えても、向きを書かない", () => {
  expect(
    writtenRotation({
      parentRotation: 512.2,
      dropRotation: 152.2,
      ownRotation: 0,
    }),
  ).toEqual(Option.none);
});

test("回したノードには揃え先が無い", () => {
  expect(
    NodeResize.resizable(setupTurnedSelection("tilted")).snapTargetNames,
  ).toEqual([]);
});

test("1 回り回したノードは回っていないものと同じく揃え先を持つ", () => {
  expect(
    NodeResize.resizable(setupTurnedSelection("stamp")).snapTargetNames,
  ).toEqual(["home", "card", "tilted"]);
});

